import{G as e,W as t,n,rt as r}from"./chunks/framework.CMPLvzN_.js";var i=JSON.parse(`{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"常识/法律/法律概念.md","filePath":"常识/法律/法律概念.md"}`),a={name:`常识/法律/法律概念.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h2 id="自首" tabindex="-1">自首 <a class="header-anchor" href="#自首" aria-label="Permalink to “自首”">​</a></h2><p>概念：犯罪以后自动投案，如实供述自己的罪行的，是自首。</p><p>亲友规劝、陪同投案的也视为自动投案</p><h2 id="行政复议" tabindex="-1">行政复议 <a class="header-anchor" href="#行政复议" aria-label="Permalink to “行政复议”">​</a></h2><p>对处罚决定不服的，则县公安局为被申请人，复议机关为<strong>县政府</strong></p><p>事实清楚、权利义务关系明确、争议不大的，适用于简易程序</p><p>行政复议机关办理行政复议案件，可以进行调解</p><p><strong>行政机关</strong>对<strong>行政机关工作人员</strong>的奖惩、任免等决定不在行政复议的范围内</p><h2 id="所有权" tabindex="-1">所有权 <a class="header-anchor" href="#所有权" aria-label="Permalink to “所有权”">​</a></h2><p>就算你买了一辆别人借来的自行车，你也可以获得该自行车的所有权。</p><p>因继承取得物权的，自继承开始时发生效力。即不需要办理变更登记就获得继承物的所有权。</p><h2 id="作伪证" tabindex="-1">作伪证 <a class="header-anchor" href="#作伪证" aria-label="Permalink to “作伪证”">​</a></h2><p>证人、鉴定人、记录人、翻译人参与虚假作证都构成<strong>作伪证罪</strong></p><h2 id="更改住宅为经营性用房" tabindex="-1">更改住宅为经营性用房 <a class="header-anchor" href="#更改住宅为经营性用房" aria-label="Permalink to “更改住宅为经营性用房”">​</a></h2><p>除遵守法律、法规以及管理规约外，应当经<strong>有利害关系的业主一致</strong>同意。</p><h2 id="对行政许可进行审查" tabindex="-1">对行政许可进行审查 <a class="header-anchor" href="#对行政许可进行审查" aria-label="Permalink to “对行政许可进行审查”">​</a></h2><p>发现行政许可事项直接关系他人重大利益的，应当告知该利害关系人，应该听取申请人、利害关系人的意见。</p><p>比如：某食品经营许可证即将到期，老板发起申请延续许可，但周边居民反映该店铺噪声大、有用电安全隐患，市场监督管理局应将这些提到的因素也纳入审查。</p><h2 id="依法行政" tabindex="-1">依法行政 <a class="header-anchor" href="#依法行政" aria-label="Permalink to “依法行政”">​</a></h2><p>包括六个方面：</p><ol><li><p>合法行政原则：合法行政是行政法的核心原则，要求行政机关的所有行为都必须遵循现行有效的法律。</p></li><li><p>合理行政原则：合理行政原则要求行政行为必须基于理性，避免武断和随意。</p></li><li><p>公平、公正原则：行政机关应平等对待行政相对人，不得差别对待。</p></li><li><p>考虑相关因素原则：作出行政处罚时，要考虑违法行为的事实、性质、情节以及社会危害程度。</p></li><li><p>比例原则：行政机关采取的措施和手段应当必要、适当，避免损害行政相对人的权益。</p></li><li><p>程序正当原则：确保行政行为的公开和透明，保障公民的知情权和参与权。</p></li></ol><h2 id="民事责任和刑事责任" tabindex="-1">民事责任和刑事责任 <a class="header-anchor" href="#民事责任和刑事责任" aria-label="Permalink to “民事责任和刑事责任”">​</a></h2><p>民事责任主要是对<strong>平等主体</strong>之间因<strong>违反民事法律规范</strong>所应承担的责任。其目的在于补偿受害方的损失，形式多样，包括赔偿损失、恢复原状、支付违约金等‌</p><p>刑事责任是因行为人<strong>违反刑事法律规范</strong>而应承担的法律责任。其目的在于<strong>惩罚犯罪行为</strong>，形式包括管制、拘役、有期徒刑、无期徒刑、死刑等‌</p>`,24)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};